import app from 'flarum/admin/app';
const url = path => `${app.forum.attribute('apiUrl')}/insert-coin/manage${path}`;
export function manage(method, path, body) {
  return app.request({
    method,
    url: url(path),
    body
  });
}

/** Multipart upload: the browser sets the boundary, Flarum's CSRF header is added by app.request. */
export function upload(path, form) {
  return app.request({
    method: 'POST',
    url: url(path),
    body: form,
    serialize: raw => raw
  });
}